    static boolean isOldPattern(String s) {
        if (s.length() != 8) return false;

        for (int i = 0; i < 3; i++) {
            if (!isUpper(s.charAt(i))) return false;
        }

        if (s.charAt(3) != '-') return false;

        for (int i = 4; i < 8; i++) {
            if (!isDigit(s.charAt(i))) return false;
        }

        return true;
    }

    static boolean isMercosulPattern(String s) {
